pub struct List<T> {
    head: Option<Box<Node<T>>>,
}

struct Node<T> {
    val: T,
    next: Option<Box<Node<T>>>,
}

impl<T> List<T> {
    pub fn new() -> Self {
        List { head: None }
    }

    pub fn push_front(&mut self, val: T) {
        let old_head = self.head.take();
        let new_node = Box::new(Node { val, next: None }); // bug: next should be old_head
        self.head = Some(new_node);
    }

    pub fn pop_front(&mut self) -> Option<T> {
        self.head.take().map(|node| {
            self.head = node.next;
            node.val
        })
        // This part is actually correct — bug was in push_front losing the chain
    }

    pub fn peek(&self) -> Option<&T> {
        self.head.as_ref().map(|n| &n.val)
    }

    pub fn len(&self) -> usize {
        let mut count = 0;
        let mut current = &self.head;
        while let Some(node) = current {
            count += 1;
            current = &node.next;
        }
        count
        // len is correct, but push_front drops nodes so len always <=1
    }

    pub fn to_vec(&self) -> Vec<&T> {
        let mut result = vec![];
        let mut current = &self.head;
        while let Some(node) = current {
            result.push(&node.val);
            current = &node.next;
        }
        result
    }
}

